insert into public.events (slug,name_hi,name_en,starts_on,ends_on,is_current,note_hi,note_en) values ('magh-mela-2027','माघ मेला 2027, प्रयागराज','Magh Mela 2027, Prayagraj','2027-01-15','2027-03-06',true,'तिथियाँ पंचांग और प्रकाशित स्रोतों पर आधारित हैं। यात्रा तय करने से पहले मेला प्राधिकरण की आधिकारिक घोषणा जरूर देखें।','Dates are based on the panchang and published sources. Check the official Mela Pradhikaran announcement before you finalise travel.') on conflict (slug) do nothing;
insert into public.snan_dates (event_id,snan_on,name_hi,name_en,crowd,tip_hi,tip_en,sort) select (select id from public.events where slug='magh-mela-2027'),'2027-01-15','मकर संक्रांति','Makar Sankranti','very_high','मेले का पहला बड़ा स्नान। सुबह सबसे ज्यादा भीड़। बच्चों और बुजुर्गों के साथ न जाएँ।','First major bath of the Mela. Heaviest crowds at dawn. Avoid with small children and elders.',1 where not exists (select 1 from public.snan_dates where snan_on='2027-01-15');
insert into public.snan_dates (event_id,snan_on,name_hi,name_en,crowd,tip_hi,tip_en,sort) select (select id from public.events where slug='magh-mela-2027'),'2027-01-22','पौष पूर्णिमा','Paush Purnima','high','कल्पवास की शुरुआत। भीड़ ज्यादा, पर मौनी अमावस्या से कम।','Kalpvas begins. Crowded, but less than Mauni Amavasya.',2 where not exists (select 1 from public.snan_dates where snan_on='2027-01-22');
insert into public.snan_dates (event_id,snan_on,name_hi,name_en,crowd,tip_hi,tip_en,sort) select (select id from public.events where slug='magh-mela-2027'),'2027-02-06','मौनी अमावस्या','Mauni Amavasya','very_high','मेले का सबसे बड़ा स्नान। सड़कें बंद और डायवर्जन सख्त रहते हैं। पहली बार वालों के लिए सबसे कठिन दिन।','The biggest bath of the Mela. Roads closed and diversions strict. The hardest day for first-timers.',3 where not exists (select 1 from public.snan_dates where snan_on='2027-02-06');
insert into public.snan_dates (event_id,snan_on,name_hi,name_en,crowd,tip_hi,tip_en,sort) select (select id from public.events where slug='magh-mela-2027'),'2027-02-11','वसंत पंचमी','Basant Panchami','high','पीले वस्त्र पहनने का चलन। भीड़ ज्यादा, सुबह जल्दी पहुँचें।','Devotees wear yellow. Crowded, so go very early.',4 where not exists (select 1 from public.snan_dates where snan_on='2027-02-11');
insert into public.snan_dates (event_id,snan_on,name_hi,name_en,crowd,tip_hi,tip_en,sort) select (select id from public.events where slug='magh-mela-2027'),'2027-02-20','माघी पूर्णिमा','Maghi Purnima','high','कल्पवास का समापन स्नान। शाम तक भीड़ रहती है।','Closing bath of Kalpvas. Crowds last into the evening.',5 where not exists (select 1 from public.snan_dates where snan_on='2027-02-20');
insert into public.snan_dates (event_id,snan_on,name_hi,name_en,crowd,tip_hi,tip_en,sort) select (select id from public.events where slug='magh-mela-2027'),'2027-03-06','महाशिवरात्रि','Mahashivratri','moderate','मेले का अंतिम स्नान। मेला समेटने लगता है, पर मंदिरों में भीड़ रहती है।','Last bath of the Mela. The Mela winds down, but temples stay busy.',6 where not exists (select 1 from public.snan_dates where snan_on='2027-03-06');
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('sangam','त्रिवेणी संगम','Triveni Sangam','ghat','Sangam','गंगा-यमुना (और अदृश्य सरस्वती) का संगम। स्नान और नाव यात्रा का मुख्य स्थान।','Where the Ganga and Yamuna (and the unseen Saraswati) meet. Main place for the holy dip and boat rides.',1) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('hanuman-mandir','बड़े हनुमान जी (लेटे हनुमान)','Bade Hanuman Ji (Reclining Hanuman)','temple','Sangam','संगम के पास प्रसिद्ध मंदिर, जहाँ हनुमान जी लेटी मुद्रा में हैं। स्नान के बाद दर्शन का चलन है।','Famous temple near the Sangam with Hanuman in a reclining pose. Visiting after the bath is customary.',2) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('akshayavat','अक्षयवट और पातालपुरी (किले में)','Akshayavat and Patalpuri (inside the Fort)','temple','Fort','किले के भीतर पवित्र वट वृक्ष और भूमिगत मंदिर। प्रवेश के नियम बदलते रहते हैं, इसलिए पहले पता कर लें।','Sacred banyan and an underground shrine inside the Fort. Entry rules change, so confirm before you go.',3) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('alopi-devi','अलोपी देवी मंदिर','Alopi Devi Temple','temple','Alopibagh','शक्तिपीठ परंपरा से जुड़ा मंदिर, जिसमें प्रतिमा नहीं बल्कि एक झूला (डोली) पूजित है।','Temple linked with the Shakti Peeth tradition, where a palanquin is worshipped instead of an idol.',4) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('mankameshwar','मनकामेश्वर मंदिर','Mankameshwar Temple','temple','Yamuna bank','यमुना किनारे प्राचीन शिव मंदिर, किले के पास।','Ancient Shiva temple on the Yamuna bank, near the Fort.',5) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('anand-bhawan','आनंद भवन और स्वराज भवन','Anand Bhawan and Swaraj Bhawan','heritage','Civil Lines','नेहरू परिवार से जुड़े ऐतिहासिक भवन, स्वतंत्रता आंदोलन का इतिहास समेटे।','Historic houses of the Nehru family, with exhibits from the freedom movement.',6) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('allahabad-museum','इलाहाबाद संग्रहालय','Allahabad Museum','heritage','Civil Lines','चंद्रशेखर आज़ाद पार्क के पास संग्रहालय, मूर्तियाँ, चित्र और ऐतिहासिक वस्तुएँ।','Museum beside Chandrashekhar Azad Park with sculpture, paintings and historical objects.',7) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('khusro-bagh','खुसरो बाग','Khusro Bagh','heritage','Near railway station','मुगलकालीन उद्यान और मकबरे, स्टेशन के पास शांत जगह।','Mughal-era garden and tombs, a quiet spot near the railway station.',8) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('medical-camps','मेला क्षेत्र में चिकित्सा शिविर','Medical camps in the Mela area','medical','Mela area','मेले में अस्थायी अस्पताल और प्राथमिक उपचार केंद्र बनते हैं। स्थान हर साल मेला नक्शे में दिए जाते हैं।','Temporary hospitals and first-aid centres are set up in the Mela. Locations are published each year on the Mela map.',9) on conflict (slug) do nothing;
insert into public.places (slug,name_hi,name_en,type,area,desc_hi,desc_en,sort) values ('khoya-paya','खोया-पाया केंद्र','Lost-and-found centres (Khoya-Paya)','facility','Mela area','बिछड़े लोगों के लिए मेले में केंद्र बनते हैं। परिवार के साथ पहले से एक मिलने की जगह तय रखें।','Centres for separated visitors are set up in the Mela. Fix a meeting spot with your family in advance.',10) on conflict (slug) do nothing;
insert into public.itineraries (slug,days,title_hi,title_en,summary_hi,summary_en,stops,sort) values ('1-day',1,'1 दिन: संगम और हनुमान जी','1 day: Sangam and Hanuman Ji','जल्दी पहुँचकर स्नान और मुख्य दर्शन, शाम तक वापसी या रात रुकना।','Reach early, bathe, see the main shrines, return by evening or stay the night.','[{"t_hi": "सुबह (सूर्योदय के आसपास)", "t_en": "Morning (around sunrise)", "hi": "संगम पर स्नान या नाव से संगम बिंदु", "en": "Holy dip at the Sangam or boat to the Sangam point", "place": "sangam"}, {"t_hi": "स्नान के बाद", "t_en": "After the bath", "hi": "बड़े हनुमान जी के दर्शन", "en": "Darshan at Bade Hanuman Ji", "place": "hanuman-mandir"}, {"t_hi": "दोपहर", "t_en": "Midday", "hi": "किले में अक्षयवट-पातालपुरी (खुला हो तो) और भोजन", "en": "Akshayavat and Patalpuri in the Fort (if open) and lunch", "place": "akshayavat"}, {"t_hi": "दोपहर बाद", "t_en": "Afternoon", "hi": "अलोपी देवी मंदिर", "en": "Alopi Devi Temple", "place": "alopi-devi"}]'::jsonb,1) on conflict (slug) do nothing;
insert into public.itineraries (slug,days,title_hi,title_en,summary_hi,summary_en,stops,sort) values ('2-day',2,'2 दिन: तीर्थ और शहर','2 days: Pilgrimage and the city','पहला दिन तीर्थ, दूसरा दिन आराम से शहर और इतिहास।','Day 1 for the shrines, day 2 for a relaxed look at the city and its history.','[{"day": 1, "t_hi": "दिन 1: सुबह", "t_en": "Day 1: Morning", "hi": "संगम स्नान और बड़े हनुमान जी", "en": "Sangam bath and Bade Hanuman Ji", "place": "sangam"}, {"day": 1, "t_hi": "दिन 1: दोपहर", "t_en": "Day 1: Afternoon", "hi": "अक्षयवट (खुला हो तो) और अलोपी देवी", "en": "Akshayavat (if open) and Alopi Devi", "place": "akshayavat"}, {"day": 2, "t_hi": "दिन 2: सुबह", "t_en": "Day 2: Morning", "hi": "मनकामेश्वर मंदिर और यमुना किनारा", "en": "Mankameshwar Temple and the Yamuna bank", "place": "mankameshwar"}, {"day": 2, "t_hi": "दिन 2: दोपहर", "t_en": "Day 2: Afternoon", "hi": "आनंद भवन, स्वराज भवन और इलाहाबाद संग्रहालय", "en": "Anand Bhawan, Swaraj Bhawan and Allahabad Museum", "place": "anand-bhawan"}, {"day": 2, "t_hi": "दिन 2: शाम", "t_en": "Day 2: Evening", "hi": "सिविल लाइंस में खान-पान और खरीदारी", "en": "Food and shopping in Civil Lines", "place": ""}]'::jsonb,2) on conflict (slug) do nothing;
insert into public.itineraries (slug,days,title_hi,title_en,summary_hi,summary_en,stops,sort) values ('3-day',3,'3 दिन: प्रयागराज के साथ काशी','3 days: Prayagraj plus Kashi','दो दिन प्रयागराज, तीसरा दिन वाराणसी (सड़क से लगभग 120 किमी, 2.5 से 3 घंटे)।','Two days in Prayagraj, day 3 in Varanasi (about 120 km by road, roughly 2.5 to 3 hours).','[{"day": 1, "t_hi": "दिन 1", "t_en": "Day 1", "hi": "संगम स्नान, बड़े हनुमान जी, अक्षयवट (खुला हो तो)", "en": "Sangam bath, Bade Hanuman Ji, Akshayavat (if open)", "place": "sangam"}, {"day": 2, "t_hi": "दिन 2", "t_en": "Day 2", "hi": "अलोपी देवी, मनकामेश्वर, आनंद भवन और संग्रहालय", "en": "Alopi Devi, Mankameshwar, Anand Bhawan and the museum", "place": "alopi-devi"}, {"day": 3, "t_hi": "दिन 3", "t_en": "Day 3", "hi": "वाराणसी: काशी विश्वनाथ दर्शन और गंगा आरती", "en": "Varanasi: Kashi Vishwanath darshan and the Ganga aarti", "place": ""}]'::jsonb,3) on conflict (slug) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('indore','इंदौर','Indore','दूरी ज्यादा है, इसलिए ट्रेन या फ्लाइट बेहतर। परिवार के साथ रात की ट्रेन पहले से बुक करें।','It is a long way, so train or flight works best. Book an overnight train early if you travel with family.','[{"mode": "train", "hi": "IRCTC पर इंदौर से प्रयागराज (PRYJ) सीधी या भोपाल/जबलपुर होकर ट्रेनें देखें। मेले के दिनों में सीटें जल्दी भर जाती हैं।", "en": "On IRCTC look for Indore to Prayagraj (PRYJ), direct or via Bhopal/Jabalpur. Seats fill fast around Mela dates."}, {"mode": "flight", "hi": "प्रयागराज हवाई अड्डा (IXD) बमरौली में है। सीधी उड़ानें सीमित हैं, इसलिए वाराणसी या लखनऊ विकल्प रखें।", "en": "Prayagraj Airport (IXD) is at Bamrauli. Direct flights are limited, so keep Varanasi or Lucknow as a backup."}, {"mode": "road", "hi": "लंबी दूरी है। परिवार के साथ सड़क से जाना थकाने वाला होगा और मेला क्षेत्र के पास वाहन रोके जाते हैं।", "en": "A long drive. Tiring with family, and vehicles are stopped well before the Mela area."}]'::jsonb,1) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('bhopal','भोपाल','Bhopal','ट्रेन सबसे आसान। कई लोग जबलपुर/कटनी होकर आते हैं।','Train is easiest. Many travellers come via Jabalpur or Katni.','[{"mode": "train", "hi": "IRCTC पर भोपाल से PRYJ की ट्रेनें देखें।", "en": "Search IRCTC for Bhopal to PRYJ trains."}, {"mode": "flight", "hi": "सीधी उड़ान कम हैं, ट्रेन ज्यादा भरोसेमंद।", "en": "Direct flights are few; trains are more dependable."}, {"mode": "road", "hi": "सड़क यात्रा लंबी है, ट्रेन बेहतर।", "en": "The road trip is long; train is better."}]'::jsonb,2) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('nagpur','नागपुर','Nagpur','ट्रेन या फ्लाइट। सतना/कटनी होकर कई ट्रेनें मिलती हैं।','Train or flight. Several trains run via Satna or Katni.','[{"mode": "train", "hi": "IRCTC पर नागपुर से प्रयागराज की ट्रेनें देखें।", "en": "Search IRCTC for Nagpur to Prayagraj trains."}, {"mode": "flight", "hi": "फ्लाइट के लिए कीमतें और उपलब्धता पहले जाँचें।", "en": "Check fares and availability early for flights."}, {"mode": "road", "hi": "सड़क से दूरी बहुत है।", "en": "Very long by road."}]'::jsonb,3) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('delhi','दिल्ली / NCR','Delhi / NCR','ट्रेन और फ्लाइट दोनों के कई विकल्प। मेले के दिनों में टिकट पहले से लें।','Plenty of train and flight options. Book ahead around Mela dates.','[{"mode": "train", "hi": "दिल्ली से PRYJ की कई ट्रेनें चलती हैं, IRCTC पर देखें।", "en": "Many Delhi to PRYJ trains run; check IRCTC."}, {"mode": "flight", "hi": "दिल्ली से प्रयागराज की उड़ानें उपलब्ध रहती हैं, पर बड़े स्नानों के आसपास महँगी और फुल।", "en": "Flights from Delhi are available but get expensive and full around big baths."}, {"mode": "road", "hi": "लगभग 600+ किमी; कार संभव है, पर स्नान के दिनों में डायवर्जन से देरी होती है।", "en": "Roughly 600+ km; a car is possible, but diversions cause delays on bath days."}]'::jsonb,4) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('lucknow','लखनऊ','Lucknow','सड़क और ट्रेन दोनों आसान, लगभग 200 किमी।','Road and train both work, about 200 km.','[{"mode": "train", "hi": "लखनऊ से प्रयागराज की ट्रेनें कई हैं।", "en": "Plenty of trains from Lucknow to Prayagraj."}, {"mode": "flight", "hi": "फ्लाइट की जरूरत कम, ट्रेन/सड़क बेहतर।", "en": "A flight is rarely needed; train or road is better."}, {"mode": "road", "hi": "एक्सप्रेसवे/हाईवे से 3.5 से 4.5 घंटे सामान्य दिनों में; स्नान के दिन ज्यादा।", "en": "About 3.5 to 4.5 hours on normal days; more on bath days."}]'::jsonb,5) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('varanasi','वाराणसी','Varanasi','सबसे नजदीकी बड़ा शहर, लगभग 120 किमी। सड़क और ट्रेन दोनों।','The nearest big city, about 120 km. Road and train both work.','[{"mode": "train", "hi": "वाराणसी से प्रयागराज के लिए रोज कई ट्रेनें और बसें।", "en": "Many daily trains and buses from Varanasi."}, {"mode": "flight", "hi": "फ्लाइट की जरूरत नहीं।", "en": "No flight needed."}, {"mode": "road", "hi": "लगभग 2.5 से 3 घंटे, स्नान के दिन ज्यादा।", "en": "About 2.5 to 3 hours, more on bath days."}]'::jsonb,6) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('kolkata','कोलकाता','Kolkata','ट्रेन से सीधी कनेक्टिविटी अच्छी है। फ्लाइट भी विकल्प।','Good direct train connectivity. A flight is also an option.','[{"mode": "train", "hi": "हावड़ा/सियालदह से PRYJ की ट्रेनें IRCTC पर देखें।", "en": "Look for Howrah/Sealdah to PRYJ on IRCTC."}, {"mode": "flight", "hi": "उड़ानें सीमित, पहले कीमत जाँचें।", "en": "Flights are limited; check fares first."}, {"mode": "road", "hi": "सड़क से बहुत दूर।", "en": "Very far by road."}]'::jsonb,7) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('mumbai','मुंबई','Mumbai','ट्रेन लंबी है; फ्लाइट समय बचाती है।','The train is long; a flight saves time.','[{"mode": "train", "hi": "मुंबई से PRYJ की ट्रेनें लंबी यात्रा हैं, पहले बुक करें।", "en": "Mumbai to PRYJ trains are a long journey; book early."}, {"mode": "flight", "hi": "सीधी उड़ानें हैं, पर बड़े स्नानों के पास भरी रहती हैं।", "en": "Direct flights exist but fill up near big baths."}, {"mode": "road", "hi": "सड़क से व्यावहारिक नहीं।", "en": "Not practical by road."}]'::jsonb,8) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('patna','पटना','Patna','ट्रेन और सड़क दोनों संभव।','Train and road are both possible.','[{"mode": "train", "hi": "पटना से PRYJ की ट्रेनें IRCTC पर देखें।", "en": "Look for Patna to PRYJ on IRCTC."}, {"mode": "flight", "hi": "फ्लाइट की जरूरत कम।", "en": "A flight is rarely needed."}, {"mode": "road", "hi": "हाईवे से सड़क यात्रा संभव, पर मेले के दिनों में डायवर्जन।", "en": "Possible by highway, but expect diversions on Mela days."}]'::jsonb,9) on conflict (city_key) do nothing;
insert into public.routes (city_key,city_hi,city_en,summary_hi,summary_en,modes,sort) values ('other','कोई और शहर','Another city','अपने शहर से IRCTC पर प्रयागराज की ट्रेनें देखें। नजदीकी बड़े हवाई अड्डे: प्रयागराज (IXD), वाराणसी, लखनऊ।','Search IRCTC from your city. Nearby airports: Prayagraj (IXD), Varanasi, Lucknow.','[{"mode": "train", "hi": "IRCTC पर अपने शहर से प्रयागराज के स्टेशन चुनें: प्रयागराज जं. (PRYJ), छिवकी (PCOI), रामबाग (PRRB), संगम (PYGS)", "en": "On IRCTC pick Prayagraj stations: Prayagraj Jn (PRYJ), Chheoki (PCOI), Rambagh (PRRB), Sangam (PYGS)"}, {"mode": "flight", "hi": "प्रयागराज (IXD), वाराणसी (VNS) या लखनऊ (LKO) देखें।", "en": "Check Prayagraj (IXD), Varanasi (VNS) or Lucknow (LKO)."}, {"mode": "road", "hi": "मेला क्षेत्र से पहले वाहन रोके जाते हैं; पार्किंग और शटल की जानकारी आधिकारिक नोटिस में देखें।", "en": "Vehicles are stopped before the Mela area; see official notices for parking and shuttles."}]'::jsonb,99) on conflict (city_key) do nothing;
