insert into public.price_guides (service,label_hi,label_en,note_hi,note_en,sort) select 'boat','संगम नाव (प्रति नाव)','Sangam boat (per boat)','बैठने से पहले रेट तय करें। आधिकारिक रेट बोर्ड हो तो उसी को मानें।','Fix the rate before you board. Follow the official rate board where one is displayed.',1 where not exists (select 1 from public.price_guides where service='boat');
insert into public.price_guides (service,label_hi,label_en,note_hi,note_en,sort) select 'auto','ऑटो / ई-रिक्शा','Auto / e-rickshaw','मेले के दिनों में किराया बढ़ता है। बैठने से पहले तय कर लें।','Fares rise on Mela days. Settle before you sit.',2 where not exists (select 1 from public.price_guides where service='auto');
insert into public.price_guides (service,label_hi,label_en,note_hi,note_en,sort) select 'guide','स्थानीय गाइड','Local guide','सिर्फ पहचान वाले या सत्यापित गाइड लें। पूरा पैकेज तय करके चलें।','Use only known or verified guides. Agree the whole package up front.',3 where not exists (select 1 from public.price_guides where service='guide');
insert into public.notices (kind,msg_hi,msg_en) select 'info','माघ मेला 2027 की तिथियाँ प्रकाशित स्रोतों पर आधारित हैं। आधिकारिक घोषणा आने पर यहाँ अपडेट होंगी।','Magh Mela 2027 dates are based on published sources. This page updates when the official announcement is out.' where not exists (select 1 from public.notices where msg_en='Magh Mela 2027 dates are based on published sources. This page updates when the official announcement is out.');
